import{_ as t,o as a,c as o,a0 as s}from"./chunks/framework.D4fUSYzX.js";const p=JSON.parse('{"title":"ADR 0036: The Auto-handoff mode is factory state, not a config setting","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0036-the-auto-handoff-mode-is-factory-state.md","filePath":"adr/0036-the-auto-handoff-mode-is-factory-state.md"}'),n={name:"adr/0036-the-auto-handoff-mode-is-factory-state.md"};function i(r,e,h,d,l,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0036-the-auto-handoff-mode-is-factory-state-not-a-config-setting" tabindex="-1">ADR 0036: The Auto-handoff mode is factory state, not a config setting <a class="header-anchor" href="#adr-0036-the-auto-handoff-mode-is-factory-state-not-a-config-setting" aria-label="Permalink to &quot;ADR 0036: The Auto-handoff mode is factory state, not a config setting&quot;">​</a></h1><p>Status: accepted Date: 2026-09-19</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The Auto-handoff mode answered two different questions with one stored value. The config file carried the startup default, and the <code>a</code> key in the Ticket section toggled a session-only copy of it: a restart, or a dev reload, dropped the mode back to the default. The operator&#39;s last choice of how the factory ran was not a fact the plane could rely on, and the plane had no durable answer to &quot;how did the factory last run&quot;.</p><p>The mode describes how the factory runs, and the factory&#39;s running facts live in the factory state (the state file). The decision was where the mode belongs, and how an existing config file that still carries the setting is treated.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>The mode is factory state on the state file.</strong> A fresh state file starts with the mode off. The <code>a</code> key in the Ticket section writes the new value to the state file at once; the in-session flip stands either way, and a write failure reports on the Message line. The plane reads the mode from the state file on startup, so a restart and a dev reload find the mode where the operator left it. The mode is per state file: two state files keep separate modes, and two configs that share one state file share the mode.</p><p><strong>The setting is removed from the config, not demoted to a default.</strong> The key leaves the config schema, and a config file that still carries the line fails startup with the existing unknown-top-level-key error, which names the key. The operator removes the line by hand; an operator who ran auto on confirms the mode once with the <code>a</code> key after the upgrade.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>The config keeps the default, and the toggle writes the config back.</strong> The plane rewrites the operator&#39;s file on every toggle, keeping the mode visible in a file the operator can read and edit, at the cost of the plane owning a file the operator owns, of full rewrites that lose comments, and of a startup precedence between two writers.</li><li><strong>A separate file for the mode.</strong> A second operator file to seed, read, and validate for one value.</li><li><strong>A self-healing migration: seed the state from the legacy line and remove the line from the file at startup.</strong> It preserves a configured value invisibly, adds a surgical edit to the operator&#39;s file on the startup path, and gives the plane a second write to that file. The hard break instead makes the operator re-confirm a safety-relevant switch once, with a readable error that names the key.</li><li><strong>A permanent legacy alias: the key stays accepted and seeds the state once.</strong> A dead key the strict validator must special-case forever, and a value that silently stops working after the first seed. The <code>ticket-sources</code> alias stayed because the setting stayed functional; a removed setting has no functional alias.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The mode is controlled only from the TUI: there is no config knob and no CLI flag.</li><li>The config file stays fully operator-owned; the Repository mapping section remains the one section the control plane writes back.</li><li>The state schema gains the mode in a new version.</li><li>The session facts that are not factory state (section collapse, selection, the history filter, the launcher draft) stay session-only.</li></ul>',12)])])}const u=t(n,[["render",i]]);export{p as __pageData,u as default};
